import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    order_info = {} # id -> dict(side, price, qty, active)
    seq_map = {}    # id -> arrival sequence number
    seq_counter = 0

    def add_to_book(oid):
        info = order_info[oid]
        seq = seq_map[oid]
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], seq, oid))
        else:
            heapq.heappush(sell_heap, (info['price'], seq, oid))

    def match_against(incoming_side, incoming_price, incoming_qty, is_market, incoming_id):
        remaining = incoming_qty
        heap = sell_heap if incoming_side == 'buy' else buy_heap
        while remaining > 0 and heap:
            top = heap[0]
            rid = top[2]
            info = order_info.get(rid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            resting_price = info['price']
            if not is_market:
                if incoming_side == 'buy' and resting_price > incoming_price:
                    break
                if incoming_side == 'sell' and resting_price < incoming_price:
                    break
            heapq.heappop(heap)
            trade_qty = min(remaining, info['qty'])
            if incoming_side == 'buy':
                trades.append([incoming_id, rid, resting_price, trade_qty])
            else:
                trades.append([rid, incoming_id, resting_price, trade_qty])
            info['qty'] -= trade_qty
            remaining -= trade_qty
            if info['qty'] > 0:
                heapq.heappush(heap, top)
            else:
                info['active'] = False
        return remaining

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in order_info:
                info = order_info[oid]
                if info['active'] and info['qty'] > 0:
                    info['active'] = False
            continue

        oid = order[1]
        seq_map[oid] = seq_counter
        seq_counter += 1

        if typ == 'limit':
            _, _, side, price, qty = order
            order_info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
            remaining = match_against(side, price, qty, False, oid)
            order_info[oid]['qty'] = remaining
            if remaining > 0:
                add_to_book(oid)
            else:
                order_info[oid]['active'] = False
        elif typ == 'ioc':
            _, _, side, price, qty = order
            order_info[oid] = {'side': side, 'price': price, 'qty': qty, 'active': True}
            match_against(side, price, qty, False, oid)
            order_info[oid]['qty'] = 0
            order_info[oid]['active'] = False
        elif typ == 'market':
            _, _, side, qty = order
            order_info[oid] = {'side': side, 'price': None, 'qty': qty, 'active': True}
            match_against(side, None, qty, True, oid)
            order_info[oid]['qty'] = 0
            order_info[oid]['active'] = False

    return trades

